    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_vec_mq_g8;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_vec_mq_split_g8;
