    // GQA=8 class (Qwen3.5/3.6-35B-A3B: 16 Q heads, 2 KV heads). o_acc =
    // DV_VEC/32 × 8 = 128B/lane (in budget); the baseline fa1 path for this
    // shape has NO MQ/FD at all and pays an 8× KV re-read per Q head.
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_vec_mq_split_g8_c32;
    // alternative decode
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_local_tile;
    // hybrid local-tile + MQ + FD-split kernel for DK=DV=128 only
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_local_mq_split;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_f16_q1_local_mq_split_g8;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_f16_bm;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_f16_bn;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_f16_wg_आकार;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_f16_split_wg_आकार;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_f16_split_nkv_threshold;
    // f32 Q / native q8_0 KV
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q8_0_q1;            // decode
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q8_0_q1_vec;        // DV-split + multi-subgroup decode
