    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q8_0_split;         // N_SPLIT>1 variant
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q8_0_split_wg_आकार;        // wg_size = bm*n_split
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q8_0_split_nkv_threshold;  // use split when n_kv >= this
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q8_0_split_bm;             // per-split BLOCK_M
    // f32 Q / native q4_0 KV
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_vec;        // DV-split + multi-subgroup decode
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_split;
    // kv-head-coalesced + flash-decoding split for q4_0 kv (dp4a K dot)
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_vec_mq_split;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_vec_mq_split_g8;
    // Cluster-parallel q4_0 decode
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_vec_mq_split_g8_c8;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_q1_vec_mq_split_c8;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_q4_0_split;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q4_0_split_wg_आकार;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q4_0_split_nkv_threshold;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       f32_q4_0_split_bm;
    // shared: flash-decoding merge + prefill prepass (kv-pad, mask-pad, blk class)
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> f32_merge;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> kv_pad_f16;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> mask_pad_f16;
    std::map<std::pair<पूर्णांक, पूर्णांक>, cl_kernel> blk_f16;
    // generic prefill tile dims (f16 / f32 paths)
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       bm;
    std::map<std::pair<पूर्णांक, पूर्णांक>, पूर्णांक>       bn;
    // attempted (variant, (dk, dv))
