    CL_CHECK(clSetKernelArg(kernel, 0, माप(cl_mem),   &extra0->तथ्य_device));
    CL_CHECK(clSetKernelArg(kernel, 1, माप(cl_ulong), &offset0));
    CL_CHECK(clSetKernelArg(kernel, 2, माप(cl_mem),   &extrad->तथ्य_device));
    CL_CHECK(clSetKernelArg(kernel, 3, माप(cl_ulong), &offsetd));
    CL_CHECK(clSetKernelArg(kernel, 4, माप(पूर्णांक),      &n));
    CL_CHECK(clSetKernelArg(kernel, 5, माप(पूर्णांक),      &ne0));
    CL_CHECK(clSetKernelArg(kernel, 6, माप(पूर्णांक),      &ne1));
    CL_CHECK(clSetKernelArg(kernel, 7, माप(पूर्णांक),      &tri_type));

    माप_प्रकार local_work_आकार[1] = { 256 };
