        माप_प्रकार global_work_आकार_t[2] = { (माप_प्रकार)width_B, (माप_प्रकार)padded_height_B };
        backend_ctx->enqueue_ndrange_kernel(kernel, 2, global_work_आकार_t, local_work_आकार_t, dst);

