                        CL_CHECK(clSetKernelArg(dk, aidx++, माप(cl_mem), &extra0_q4_K->dm));
                        CL_CHECK(clSetKernelArg(dk, aidx++, माप(cl_mem), &extra0_q4_K->s));
                        CL_CHECK(clSetKernelArg(dk, aidx++, माप(cl_mem), &backend_ctx->prealloc_moe_qa.बफर));
